    /**
     * Handles loading a Enterprise using a UUID
     * @param		UUID uuid 
     * @return		Enterprise
     */    
    @GetMapping("/load")
    public Enterprise load( @RequestParam(required=true) UUID uuid ) {    	
    	Enterprise entity = null;

    	try {  
    		entity = service.getEnterprise( new EnterpriseFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Enterprise using Id " + uuid );
            return null;
        }

        return entity;
    }

