    @GetMapping("/")
    public List<Enterprise> loadAll() {                
    	List<Enterprise> enterpriseList = null;
        
    	try {
            // load the Enterprise
            enterpriseList = service.getAllEnterprise();
            
            if ( enterpriseList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Enterprises" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Enterprises ", exc );
        	return null;
        }

        return enterpriseList;
                            
    }


